-- Official fixed read contracts. Preserve all existing prices, grants, rollout states and legacy routes.
ON CONFLICT DO NOTHING;

SELECT provider_key, operation_key, 1, 'database', 'disabled', '{}'::uuid[], 1, 'migration-114'
FROM control.external_platform_operation_releases
WHERE contract_version = 'mx-insight-hub.native-forwarding.v1' AND release_revision = 1
ON CONFLICT DO NOTHING;

SELECT gen_random_uuid(), provider_key, operation_key, NULL, 1, NULL, desired_state, canary_consumer_ids,
       'migration-114', 'Native forwarding starts disabled; review endpoint procurement price and activate explicitly'
FROM control.external_platform_operation_policies
WHERE updated_by = 'migration-114' AND revision = 1
ON CONFLICT DO NOTHING;
